import pandas as pd
import numpy as np


def _is_null(x):
    if x is None:
        return True
    try:
        if isinstance(x, float) and np.isnan(x):
            return True
    except TypeError:
        pass
    if isinstance(x, str):
        return False
    try:
        return pd.isna(x)
    except (TypeError, ValueError):
        return False


def _null_safe_eq(a, b):
    na, nb = _is_null(a), _is_null(b)
    if na and nb:
        return True
    if na or nb:
        return False
    return a == b


def _label_eq(a, b):
    na, nb = _is_null(a), _is_null(b)
    if na and nb:
        return True
    if na or nb:
        return False
    sa = a.rstrip() if isinstance(a, str) else a
    sb = b.rstrip() if isinstance(b, str) else b
    return sa == sb


def run(inputs):
    prev = inputs["snap_prev"].copy()
    curr = inputs["snap_curr"].copy()

    prev = prev.rename(columns={
        "price": "price_prev",
        "stock": "stock_prev",
        "label": "label_prev",
    })
    curr = curr.rename(columns={
        "price": "price_curr",
        "stock": "stock_curr",
        "label": "label_curr",
    })

    merged = pd.merge(
        prev, curr,
        on=["region", "sku"],
        how="outer",
        indicator=True,
    )

    rows = []

    for _, row in merged.iterrows():
        region = row["region"]
        sku = row["sku"]
        ind = row["_merge"]

        if ind == "left_only":
            rows.append({
                "region": region,
                "sku": sku,
                "change_type": "D",
                "changed_cols": None,
            })
        elif ind == "right_only":
            rows.append({
                "region": region,
                "sku": sku,
                "change_type": "I",
                "changed_cols": None,
            })
        else:
            diffs = []
            if not _null_safe_eq(row["price_prev"], row["price_curr"]):
                diffs.append("price")
            if not _null_safe_eq(row["stock_prev"], row["stock_curr"]):
                diffs.append("stock")
            if not _label_eq(row["label_prev"], row["label_curr"]):
                diffs.append("label")

            if diffs:
                rows.append({
                    "region": region,
                    "sku": sku,
                    "change_type": "U",
                    "changed_cols": ",".join(diffs),
                })

    out = pd.DataFrame(rows, columns=["region", "sku", "change_type", "changed_cols"])
    if not out.empty:
        out = out.sort_values(["region", "sku"]).reset_index(drop=True)

    return {"change_log": out}
